46	std::string stage_qemu_cfg(const std::string& workdir, const RunResult& probe) {
47	  if (probe.spawn_failed || probe.timed_out || probe.rc != 0 || probe.out.empty())
48	    return "";
49	  const std::string path = workdir + "/qemu.cfg";
50	  std::ofstream f(path, std::ios::binary | std::ios::trunc);
51	  f.write(probe.out.data(), static_cast<std::streamsize>(probe.out.size()));
52	  if (!f) return "";
53	  return path;
