126	std::vector<std::vector<std::string>> plan_argvs(
127	    const Plan& plan, const std::vector<EngineDescriptor>& engines,
128	    const std::string& workdir, const RuntimeCtx& ctx, std::string& err) {
129	  std::vector<std::vector<std::string>> out;
130	  out.reserve(plan.steps.size());
131	  std::string prev_state_out;  // empty for the cold first leg
132	
133	  // hw-config sync: {vlen} comes from the accurate-leg engine's descriptor.
134	  long vlen = 0;
135	  // LM content transport (ROADMAP_ilm_dlm F3): the accurate engine's local
136	  // memory sizes (bytes, from its descriptor) arm the QEMU plugin's sidecar
137	  // drain and the vsim leg's --ilm/--dlm backdoor load. 0 = that engine has
138	  // no such memory -> neither leg grows an arg.
139	  long ilm_size = 0, dlm_size = 0;
140	  for (const Step& s : plan.steps)
141	    if (s.role == "accurate-leg")
142	      if (const EngineDescriptor* e = find_engine(engines, s.engine_id)) {
143	        if (e->vlen > 0) vlen = e->vlen;
144	        if (e->ilm_size > 0) ilm_size = e->ilm_size;
145	        if (e->dlm_size > 0) dlm_size = e->dlm_size;
146	      }
147	  const std::string vlen_str = std::to_string(synced_vlen(vlen));
148	  std::string lm_suffix;
149	  if (ilm_size > 0) lm_suffix += ",ilm_size=" + std::to_string(ilm_size);
150	  if (dlm_size > 0) lm_suffix += ",dlm_size=" + std::to_string(dlm_size);
151	
152	  for (size_t i = 0; i < plan.steps.size(); ++i) {
153	    const Step& step = plan.steps[i];
154	    const EngineDescriptor* eng = find_engine(engines, step.engine_id);
155	    if (!eng) {
156	      err = "plan step " + std::to_string(i) + ": unknown engine '" +
157	            step.engine_id + "'";
158	      return {};
159	    }
160	    const std::vector<std::string>* tmpl = eng->invoke_for(step.role);
161	    if (!tmpl) {
162	      err = "plan step " + std::to_string(i) + ": engine '" + step.engine_id +
163	            "' has no invoke template for role '" + step.role + "'";
164	      return {};
165	    }
166	
167	    std::string trig_err;
168	    const LegTriggerArgs lt = leg_trigger_args(step.trigger, step.role, trig_err);
169	    if (!trig_err.empty()) {
170	      err = "plan step " + std::to_string(i) + ": " + trig_err;
171	      return {};
172	    }
173	
174	    const std::string state_out = state_path(workdir, i);
175	    const std::map<std::string, std::string> m = {
176	        {"bin", eng->bin_path},
177	        {"elf", plan.elf},
178	        {"plugin", ctx.plugin_path},
179	        {"mmap", ctx.mmap_path},
180	        {"mmap_size", std::to_string(ctx.mem_size)},
181	        {"mmap_base", ctx.mmap_base},
182	        {"state_in", prev_state_out},
183	        {"state_out", state_out},
184	        // {trigger} is the qemu plugin comma-suffix: trigger args (empty for
185	        // marker) plus the LM sidecar-drain args (empty for a no-LM engine).
186	        {"trigger", lt.plugin_suffix + lm_suffix},
187	        {"vlen", vlen_str},
188	    };
189	    std::vector<std::string> argv = build_argv(*tmpl, m, err);
190	    if (!err.empty()) {
191	      err = "plan step " + std::to_string(i) + ": " + err;
192	      return {};
193	    }
194	    // The QEMU producer leg loads the accurate engine's ISA via -readconfig (its
195	    // config.inc distilled to per-extension globals), so QEMU1 executes the same
196	    // extensions the engine models. Empty => keep the descriptor's default -cpu.
197	    if (step.role == "fast-leg" && !ctx.qemu_cfg.empty()) {
198	      argv.push_back("-readconfig");
199	      argv.push_back(ctx.qemu_cfg);
200	    }
201	    // LM content transport (F3): point the vsim leg at the sidecars its
202	    // producer drained next to state_in (--ilm/--dlm backdoor load).
203	    if (step.role == "accurate-leg") {
204	      if (ilm_size > 0) {
205	        argv.push_back("--ilm");
206	        argv.push_back(prev_state_out + ".ilm");
207	      }
208	      if (dlm_size > 0) {
209	        argv.push_back("--dlm");
210	        argv.push_back(prev_state_out + ".dlm");
211	      }
212	    }
213	    // Trigger's vsim tokens, then user-forwarded per-leg flags -- both verbatim
214	    // after the filled template (matches tests/e2e.sh's ordering).
215	    argv.insert(argv.end(), lt.extra.begin(), lt.extra.end());
216	    argv.insert(argv.end(), step.extra_args.begin(), step.extra_args.end());
217	    out.push_back(std::move(argv));
218	    prev_state_out = state_out;
219	  }
220	  err.clear();
221	  return out;
222	}
223	
224	PlanResult run_plan(const Plan& plan,
225	                    const std::vector<EngineDescriptor>& engines,
226	                    const PlanOptions& opts) {
227	  PlanResult res;
228	  if (plan.steps.empty()) {
229	    res.error = "plan has no steps";
230	    return res;
231	  }
232	
233	  // Acquire the shared mmap: allocate one (and own it) when none is pinned.
234	  std::string mmap_path = plan.mmap_path;
235	  const bool own_mmap = mmap_path.empty();
236	  if (own_mmap) {
237	    std::string err;
238	    // L26/F2: back the mmap with one V-scratch page above the program's RAM.
239	    mmap_path = allocate(physical_mmap_bytes(plan.mem_size), err);
240	    if (mmap_path.empty()) {
241	      res.error = err;
242	      return res;
243	    }
244	  }
245	
246	  // A private dir for the threaded drain files.
247	  std::error_code ec;
248	  fs::path workdir = fs::temp_directory_path(ec) / "andesim-plan-XXXXXX";
249	  std::string tmpl = workdir.string();
250	  std::vector<char> tbuf(tmpl.begin(), tmpl.end());
251	  tbuf.push_back('\0');
252	  const char* made = ::mkdtemp(tbuf.data());
253	  if (!made) {
254	    if (own_mmap) ::unlink(mmap_path.c_str());
255	    res.error = "failed to create plan work dir";
256	    return res;
257	  }
258	  const std::string wd = made;
259	
260	  RuntimeCtx ctx;
261	  ctx.mmap_path = mmap_path;
262	  // L26/F2: the legs (QEMU backend size, vsim --shared-mem-size) see the
263	  // PHYSICAL window -- program RAM plus the V-scratch page. The program's own
264	  // linker script still uses only --mem-size, so the scratch page sits above
265	  // everything it can address.
266	  ctx.mem_size = physical_mmap_bytes(plan.mem_size);
267	  ctx.plugin_path = resolve_plugin(opts.plugin_path);  // mmap_base keeps its "0x0" default
268	
269	  // Match the QEMU producer leg's ISA to the accurate engine: ask that engine
270	  // for a QEMU -readconfig cfg distilled from its config.inc. Tolerant -- an
271	  // engine without --print-qemu-config leaves qemu_cfg empty (the parser throws
272	  // on the unknown flag -> non-zero exit), so the fast leg keeps its -cpu.
273	  for (const Step& s : plan.steps)
274	    if (s.role == "accurate-leg")
275	      if (const EngineDescriptor* e = find_engine(engines, s.engine_id);
276	          e && !e->bin_path.empty()) {
277	        ctx.qemu_cfg = stage_qemu_cfg(
278	            wd, run_process({e->bin_path, "--print-qemu-config"}, kQemuCfgProbeMs));
279	        break;
280	      }
281	
282	  std::string err;
283	  const std::vector<std::vector<std::string>> argvs =
284	      plan_argvs(plan, engines, wd, ctx, err);
285	  if (!err.empty()) {
286	    res.error = err;
287	  } else if (opts.dry_run) {
288	    // Build-only: the argvs are fully resolved (placeholders, staged qemu_cfg,
289	    // threaded state paths) -- record them for the caller to print, spawn none.
290	    res.argvs = argvs;
291	  } else {
292	    res.argvs = argvs;
293	    for (size_t i = 0; i < argvs.size(); ++i) {
294	      const RunResult r = run_process(argvs[i], opts.timeout_ms);
295	      if (r.spawn_failed) {
296	        res.error = "plan step " + std::to_string(i) + ": failed to spawn";
297	        break;
298	      }
299	      if (r.timed_out) {
300	        res.error = "plan step " + std::to_string(i) + ": timed out after " +
301	                    std::to_string(opts.timeout_ms) + " ms";
302	        break;
303	      }
304	      if (r.rc != opts.expect_rc) {
305	        res.error = plan_step_rc_error(i, plan.steps[i], opts.expect_rc, r.rc);
306	        break;
307	      }
308	      const StateFile sf = read_state_file(state_path(wd, i));
309	      if (!sf.ok()) {
310	        res.error = "plan step " + std::to_string(i) + ": " + sf.error;
311	        break;
312	      }
313	      res.phases.push_back({sf.st.mcycle, sf.st.minstret, r.out, sf.st});
314	    }
315	  }
316	
317	  fs::remove_all(wd, ec);
318	  if (own_mmap) ::unlink(mmap_path.c_str());
319	  return res;
320	}
321	
322	}  // namespace andes_sim
